  method LinearSearch0<T(==)>(list: seq<T>, P: T -> bool) returns (index: int)
    ensures 0 <= index <= |list|
    ensures index < |list| ==> P(list[index])
    ensures forall i :: 0 <= i < index ==> !P(list[i])
  {
